alter table public.pos_terminals drop constraint if exists pos_terminals_status_check;
update public.pos_terminals set status='INACTIVE' where status='DISABLED';
alter table public.pos_terminals add constraint pos_terminals_status_check check(status in ('CREATED','ACTIVE','INACTIVE','ARCHIVED'));
alter table public.pos_terminals add column if not exists location text;
create or replace function public.transition_pos_terminal(p_terminal_id uuid,p_action text,p_device_identifier text default null) returns public.pos_terminals language plpgsql security definer set search_path=public as $$ declare t public.pos_terminals%rowtype; action text:=upper(trim(p_action)); begin if not public.has_pos_permission('settings.manage') then raise exception 'INSUFFICIENT_PERMISSION'; end if; select * into t from public.pos_terminals where id=p_terminal_id for update; if not found then raise exception 'TERMINAL_NOT_FOUND'; end if; if action='REGISTER' then update public.pos_terminals set registration_status='REGISTERED',device_identifier=coalesce(nullif(trim(p_device_identifier),''),device_identifier),registered_at=now(),registered_by=auth.uid(),status=case when status='CREATED' then 'INACTIVE' else status end,updated_at=now() where id=t.id returning * into t; elsif action='ACTIVATE' then if t.registration_status<>'REGISTERED' then raise exception 'TERMINAL_NOT_REGISTERED'; end if; if not exists(select 1 from public.branches b join public.companies c on c.id=b.company_id where b.id=t.branch_id and b.status='ACTIVE' and c.status='ACTIVE') then raise exception 'BRANCH_OR_COMPANY_INACTIVE'; end if; update public.pos_terminals set status='ACTIVE',updated_at=now() where id=t.id returning * into t; elsif action='DEACTIVATE' then update public.pos_terminals set status='INACTIVE',updated_at=now() where id=t.id returning * into t; else raise exception 'INVALID_TERMINAL_ACTION'; end if; perform public.write_pos_audit_diff('TERMINAL_'||action,'TERMINAL',t.id,null,null,jsonb_build_object('branchId',t.branch_id,'status',t.status,'registrationStatus',t.registration_status)); return t; end $$;
create or replace function public.heartbeat_pos_terminal(p_terminal_id uuid,p_device_identifier text) returns boolean language plpgsql security definer set search_path=public as $$ begin update public.pos_terminals set last_seen_at=now() where id=p_terminal_id and device_identifier=p_device_identifier and registration_status='REGISTERED' and status='ACTIVE'; return found; end $$;
grant execute on function public.transition_pos_terminal(uuid,text,text),public.heartbeat_pos_terminal(uuid,text) to authenticated;
